static std::vector<std::string> repoNames(bool none=false){std::vector<std::string> names;if(none)names.push_back("None");for(auto& r:repos)names.push_back(r.name);return names;}
static void materialSlot(const char* title,std::string& material){if(AL_HAS(material_picker)){char text[512]{};std::snprintf(text,sizeof text,"%s",material.c_str());if(host->material_picker(title,text,sizeof text)){material=text;changed();}}else textInput(title,material);}
static void clearBuilder(Builder& b){for(size_t i=0;i<b.levelData.layers.size();i++)if(b.rebuildBottomLayers||int(i)==b.currentLayer){b.levelData.layers[i].valid=false;std::fill(b.levelData.layers[i].blocks.begin(),b.levelData.layers[i].blocks.end(),0);}changed();}
static void layerControl(Builder& b){if(b.levelData.layers.size()<2)return;checkbox("R",b.rebuildBottomLayers);host->same_line();line("Rebuild all lower layer as well");line("Layer: "+std::to_string(b.currentLayer));if(button("UP")){if(size_t(b.currentLayer)<b.levelData.layers.size()&&b.levelData.layers[b.currentLayer].valid){b.currentLayer=std::min(b.currentLayer+1,int(b.levelData.layers.size())-1);changed();}else message="you need to build the layer fully before editing upper layer!";}host->same_line();if(button("Down")&&b.currentLayer>0){auto& l=b.levelData.layers[b.currentLayer];l.valid=false;std::fill(l.blocks.begin(),l.blocks.end(),0);b.currentLayer--;changed();}}
static void exportPreview(){if(preview.map.empty()||previewKey!=stateKey())throw std::runtime_error("Generate a fresh preview before Export.");auto b=currentBuilder();auto name="plugin-autolevel-export-"+(b?b->uid:std::string("group"))+".map";writeData(name,preview.map);message="Saved ftebroom/data/"+name+". OBJ export is available after Apply through the editor.";}
