void drawBuilders(){line("Builders Groups");auto groups=groupBuilders(builders);for(size_t g=0;g<groups.size();g++){if(button("Select##group"+std::to_string(g))){groupIndex=g;changed();}if(section("Group "+std::to_string(g),int(g)==groupIndex)){for(auto i:groups[g])checkbox(builders[i].name+"##groupmember"+std::to_string(i),builders[i].selected);}}if(auto b=currentBuilder())layerControl(*b);if(auto b=currentBuilder())checkbox("MT",b->useMultiThreadedSolver);if(button("Rebuild"))startJob(false,true);host->same_line();if(button("Clear##group")&&groupIndex>=0&&size_t(groupIndex)<groups.size())for(auto i:groups[groupIndex])if(builders[i].selected)clearBuilder(builders[i]);if(button("Save##group"))saveAll(true);checkbox("MC##group",settings.combineMeshBeforeExport);host->same_line();if(button("Export##group"))exportPreview();{Disable unavailable(preview.map.empty());if(button("Apply group to map"))applyPreview();}}
